<script setup lang="ts">
import {computed} from 'vue';
import {BarChart3,CheckCircle2,LayoutDashboard} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{creation:Item;impact:string}>();
const selection=computed<Item>(()=>props.creation.selection??{});
const sample=computed<Item>(()=>props.creation.preview??{});
const rows=computed<Item[]>(()=>Array.isArray(sample.value.rows)?sample.value.rows.slice(0,25):[]);
const values=computed(()=>rows.value.map(row=>row.value).filter((value):value is number=>typeof value==='number'&&Number.isFinite(value)));
const minimum=computed(()=>Math.min(0,...values.value));const maximum=computed(()=>Math.max(0,...values.value));const span=computed(()=>maximum.value-minimum.value||1);const zero=computed(()=>-minimum.value/span.value*100);
function bar(value:unknown){const number=typeof value==='number'&&Number.isFinite(value)?value:0;return{left:(number<0?zero.value+number/span.value*100:zero.value)+'%',width:Math.abs(number)/span.value*100+'%'};}
const segments=computed(()=>{const result:string[]=[];let points:string[]=[];rows.value.forEach((row,index)=>{if(typeof row.value!=='number'||!Number.isFinite(row.value)){if(points.length)result.push(points.join(' '));points=[];return;}const x=rows.value.length<2?50:index/(rows.value.length-1)*100;const y=90-(row.value-minimum.value)/span.value*80;points.push(`${x},${y}`);});if(points.length)result.push(points.join(' '));return result;});
function formatted(value:unknown){if(typeof value!=='number'||!Number.isFinite(value))return 'Sem valor numérico';return new Intl.NumberFormat('pt-BR',sample.value.format==='currency'?{style:'currency',currency:'BRL',maximumFractionDigits:2}:sample.value.format==='integer'?{maximumFractionDigits:0}:sample.value.format==='decimal'?{minimumFractionDigits:2,maximumFractionDigits:2}:{maximumFractionDigits:4}).format(value);}
const checkedAt=computed(()=>{const date=new Date(sample.value.checked_at);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}).format(date):'';});
</script>
<template>
 <section class="dashboard-blueprint-review" aria-label="Prévia e configuração do novo dashboard">
  <div class="dashboard-blueprint-title"><LayoutDashboard :size="20"/><div><strong>{{creation.name}}</strong><p>Uma nova aba privada · {{creation.widget_count}} componentes</p></div></div>
  <dl class="dashboard-blueprint-fields"><div><dt>Informação medida</dt><dd>{{selection.metric?.label}}<small>{{selection.metric?.table_name}}</small></dd></div><div><dt>Cálculo escolhido</dt><dd>{{selection.aggregation_label}}</dd></div><div><dt>Comparação</dt><dd>{{selection.group_title}}<small>{{selection.group?.table_name}}</small></dd></div><div><dt>Visualização</dt><dd>{{selection.chart_type==='line'?'Indicador, evolução no tempo e tabela':'Indicador, comparação por categoria e tabela'}}</dd></div></dl>
  <p class="dashboard-sample-note">{{creation.filter_behavior}}</p>
  <div class="dashboard-sample-title"><BarChart3 :size="17"/><strong>Prévia dos dados consultados</strong><small v-if="checkedAt">{{checkedAt}} · Brasília</small></div>
  <p class="dashboard-sample-scope">{{sample.scope}}</p>
  <div class="dashboard-sample-kpi"><span>{{sample.metric_title}}</span><strong>{{formatted(sample.value)}}</strong></div>
  <div v-if="rows.length" class="dashboard-sample-groups"><svg v-if="sample.chart_type==='line'&&values.length" class="dashboard-sample-line" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" :aria-label="'Evolução de '+sample.metric_title+' por '+sample.group_title"><line x1="0" y1="90" x2="100" y2="90"/><polyline v-for="(points,index) in segments" :key="index" :points="points"/></svg><table><caption>{{sample.group_title}} · {{rows.length}} {{rows.length===1?'grupo na amostra':'grupos na amostra'}}</caption><thead><tr><th scope="col">{{sample.group_title}}</th><th scope="col">{{sample.metric_title}}</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index"><th scope="row">{{row.label}}</th><td><div v-if="sample.chart_type!=='line'" class="dashboard-sample-bar" aria-hidden="true"><i :style="{left:zero+'%'}"></i><span :style="bar(row.value)"></span></div><span>{{formatted(row.value)}}</span></td></tr></tbody></table></div>
  <p v-else class="dashboard-sample-note">A consulta não devolveu categorias nesta amostra. Confira os filtros e o acesso às tabelas antes de concluir sobre a ausência de dados.</p>
  <p v-if="sample.truncated" class="dashboard-sample-note">Esta amostra é parcial. O limite de apresentação é de 25 grupos.</p>
  <div v-if="creation.coverage?.verified" class="dashboard-blueprint-coverage"><CheckCircle2 :size="17"/><p><strong>Atualização dos dados conferida</strong><span>{{creation.coverage.source_count}} {{creation.coverage.source_count===1?'fonte':'fontes'}} · agenda ao menos diária e carga concluída. As agendas existentes serão preservadas.</span></p></div>
  <p class="dashboard-preservation">{{creation.dashboard_count_before}} {{creation.dashboard_count_before===1?'dashboard existente será preservado':'dashboards existentes serão preservados'}}.</p><p class="dashboard-blueprint-impact">{{impact}}</p>
 </section>
</template>
