eight:500;width:43%}.dashboard-sample-groups td{text-align:right}.dashboard-sample-groups tbody tr:last-child :is(th,td){border-bottom:0}.dashboard-sample-bar{height:8px;position:relative;margin-bottom:7px;background:#f1f5fc;border-radius:3px}.dashboard-sample-bar>i{position:absolute;top:-2px;bottom:-2px;width:1px;background:#b5c9e5}.dashboard-sample-bar>span{position:absolute;top:0;bottom:0;background:#0861ee;border-radius:2px}.dashboard-sample-line{display:block;box-sizing:border-box;width:100%;height:120px;padding:12px 16px;background:#f7faff}.dashboard-sample-line line{stroke:#d5e2f6;stroke-width:.8}.dashboard-sample-line polyline{fill:none;stroke:#0861ee;stroke-width:2;stroke-linejoin:round;stroke-linecap:round;vector-effect:non-scaling-stroke}.dashboard-sample-scope,.dashboard-sample-note,.dashboard-preservation{font-size:11px;color:#8595ad;line-height:1.8;margin:12px 0}.dashboard-blueprint-coverage{display:flex;gap:9px;align-items:flex-start;background:#eef8f3;border-radius:8px;padding:12px;color:#428368;margin:17px 0}.dashboard-blueprint-coverage>svg{flex-shrink:0;margin-top:2px}.dashboard-blueprint-coverage p{margin:0;line-height:1.7;font-size:11px}.dashboard-blueprint-coverage span{display:block;color:#6f9888;margin-top:4px}.dashboard-blueprint-impact{padding:12px;border-radius:8px;background:#fff8eb;font-size:12px;color:#816a40;line-height:1.8;margin:12px 0 0}@media(max-width:600px){.dashboard-blueprint-fields{grid-template-columns:minmax(0,1fr);gap:13px}.dashboard-sample-title small{margin-left:0;width:100%;padding-left:24px}.dashboard-sample-kpi>strong{font-size:27px}.dashboard-sample-groups th,.dashboard-sample-groups td{padding:9px}}
</style>
